import { test } from 'node:test';
import assert from 'node:assert/strict';
import { setup,source,NOW,doseBlock } from './support.js';
import { manualBlock } from '../../src/digitiser.js';
import { generateDrafts } from '../../src/draft.js';
import { approveNode,editNode,rejectNode,reviewHistory } from '../../src/review.js';
function draft(s) {const src=source(s);manualBlock(s,src.sha256,doseBlock);return generateDrafts(s,src.sha256,{atc_by_block:{b1:'P01BF01'}},{actor:'placeholder-editor',now:NOW}).nodes[0].node;}
test('two distinct reviewers approve same hash; duplicate is idempotent',t=>{const s=setup(t),n=draft(s);const a=approveNode(s,n.id,{reviewer:'a'},{now:NOW});assert.equal(a.node.status,'draft');assert.equal(a.approvals.length,1);assert.equal(approveNode(s,n.id,{reviewer:'a'},{now:NOW}).approvals.length,1);const b=approveNode(s,n.id,{reviewer:'b'},{now:NOW});assert.equal(b.node.status,'approved');assert.ok(b.approvals.every(r=>r.content_hash===b.content_hash));});
test('edits preserve history with hashes and reset approvals even when submitted by previous approver',t=>{const s=setup(t),n=draft(s);approveNode(s,n.id,{reviewer:'a'},{now:NOW});const changed=editNode(s,n.id,{applies_to:{atc:'PLACEHOLDER-OTHER'}},{actor:'editor',now:NOW});assert.equal(changed.node.status,'draft');assert.deepEqual(changed.approvals,[]);const event=reviewHistory(s,n.id).at(-1);assert.equal(event.kind,'edited');assert.notEqual(event.before_hash,event.after_hash);assert.equal(event.actor,'editor');assert.equal(event.occurred_at,NOW);assert.equal(approveNode(s,n.id,{reviewer:'b'},{now:NOW}).node.status,'draft');assert.throws(()=>editNode(s,n.id,{unexpected:true},{actor:'a',now:NOW}),/unknown/);});
test('rejection resets approvals, records reason, and parse errors cannot be approved',t=>{const s=setup(t),n=draft(s);approveNode(s,n.id,{reviewer:'a'},{now:NOW});assert.equal(rejectNode(s,n.id,{reviewer:'b',reason:'PLACEHOLDER correction needed'},{now:NOW}).approvals.length,0);assert.match(reviewHistory(s,n.id).at(-1).snapshot.reason,/correction/);const changed=editNode(s,n.id,{bands:[]},{actor:'editor',now:NOW});assert.ok(changed.node.parse_errors.length);assert.throws(()=>approveNode(s,n.id,{reviewer:'a'},{now:NOW}),/cannot approve/);});
